from __future__ import annotations
from typing import Callable, Hashable, List, Sequence, Tuple

Residue = Tuple[int, ...]


def lower_half_selector(d: Residue, mods: Sequence[int]) -> Tuple[bool, ...]:
    """k sign bits: is each coordinate in the lower half {0,...,(p-1)/2}?"""
    return tuple(2 * (x % m) < m for x, m in zip(d, mods))


def certify_refinement(P: Sequence[Residue], Q: Sequence[Residue], mods: Sequence[int]) -> bool:
    """Check that ((N, s), sel(d)) has exactly the same fibres as (s, d).

    This is the constructive content of the refinement ceiling: once it holds,
    I(T; s, d) <= I(T; N, s) + k for EVERY label T.
    """
    def key_joint(i: int) -> Hashable:
        s = tuple((a + b) % m for a, b, m in zip(P[i], Q[i], mods))
        d = tuple((b - a) % m for a, b, m in zip(P[i], Q[i], mods))
        return (s, d)

    def key_aug(i: int) -> Hashable:
        N = tuple(a * b % m for a, b, m in zip(P[i], Q[i], mods))
        s = tuple((a + b) % m for a, b, m in zip(P[i], Q[i], mods))
        d = tuple((b - a) % m for a, b, m in zip(P[i], Q[i], mods))
        return (N, s, lower_half_selector(d, mods))

    n = len(P)
    return all((key_joint(i) == key_joint(j)) == (key_aug(i) == key_aug(j))
               for i in range(n) for j in range(n))


if __name__ == "__main__":
    import random
    rng = random.Random(0)
    mods = [7, 11]
    P = [tuple(rng.randrange(m) for m in mods) for _ in range(200)]
    Q = [tuple(rng.randrange(m) for m in mods) for _ in range(200)]
    print("selector certificate holds:", certify_refinement(P, Q, mods))
    # On Z/9 the lower-half bit fails: 0, 3, 6 all square to 0.
    print([d for d in range(9) if d * d % 9 == 0])
